const canvasSketch = require('canvas-sketch');
const random = require('canvas-sketch-util/random');
const math = require('canvas-sketch-util/math');
const Tweakpane = require('tweakpane');

const settings = {
  dimensions: [window.innerWidth, window.innerHeight],
  animate: true
};

const params = {
  cols: 21,
  rows: 28,
  scaleMin: 1,
  scaleMax: 30,
  freq: 0.001,
  amp: 0.2,
  frame: 0,
  animate: true,
  lineCap: 'butt',
};

// Colores vaporwave
const colors = [
  'rgba(255, 110, 199, 0.85)', // pink
  'rgba(34, 211, 238, 0.8)',   // cyan
  'rgba(217, 70, 239, 0.8)',   // magenta
  'rgba(168, 85, 247, 0.75)',  // purple
];

const sketch = ({ canvas }) => {
  // Adaptar al resize
  window.addEventListener('resize', () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  });

  return ({ context, width, height, frame }) => {
    // Fondo negro
    context.fillStyle = '#0A0A0A';
    context.fillRect(0, 0, width, height);

    const cols = params.cols;
    const rows = params.rows;
    const numCells = cols * rows;

    const gridw = width * 0.85;
    const gridh = height * 0.85;
    const cellw = gridw / cols;
    const cellh = gridh / rows;
    const margx = (width - gridw) * 0.5;
    const margy = (height - gridh) * 0.5;

    const f = params.animate ? frame : params.frame;

    for (let i = 0; i < numCells; i++) {
      const col = i % cols;
      const row = Math.floor(i / cols);

      const x = col * cellw;
      const y = row * cellh;
      const w = cellw * 0.8;

      const n = random.noise3D(x, y, f * 10, params.freq);
      const angle = n * Math.PI * params.amp;
      const scale = math.mapRange(n, -1, 1, params.scaleMin, params.scaleMax);

      // Color vaporwave según posición
      const colorIndex = Math.floor((col / cols + row / rows) * colors.length) % colors.length;
      context.strokeStyle = colors[colorIndex];

      context.save();
      context.translate(x + margx, y + margy);
      context.translate(cellw * 0.5, cellh * 0.5);
      context.rotate(angle);

      context.lineWidth = scale;
      context.lineCap = params.lineCap;

      context.beginPath();
      context.moveTo(w * -0.5, 0);
      context.lineTo(w * 0.5, 0);
      context.stroke();

      context.restore();
    }
  };
};

// ---------- Tweakpane (ocultable) ----------
const createPane = () => {
  const pane = new Tweakpane.Pane({ title: 'Controls' });
  pane.hidden = false; // empieza visible

  let folder;

  folder = pane.addFolder({ title: 'Grid' });
  folder.addInput(params, 'lineCap', {
    options: { butt: 'butt', round: 'round', square: 'square' }
  });
  folder.addInput(params, 'cols', { min: 2, max: 50, step: 1 });
  folder.addInput(params, 'rows', { min: 2, max: 50, step: 1 });
  folder.addInput(params, 'scaleMin', { min: 1, max: 100 });
  folder.addInput(params, 'scaleMax', { min: 1, max: 100 });

  folder = pane.addFolder({ title: 'Noise' });
  folder.addInput(params, 'freq', { min: -0.01, max: 0.01 });
  folder.addInput(params, 'amp', { min: 0, max: 1 });
  folder.addInput(params, 'animate');
  folder.addInput(params, 'frame', { min: 0, max: 999 });

  // Botón para ocultar / mostrar el panel
  const btn = document.createElement('button');
  btn.textContent = 'Hide Controls';
  btn.style.cssText = `
    position: fixed;
    bottom: 20px;
    right: 20px;
    z-index: 9999;
    padding: 8px 14px;
    background: rgba(13, 2, 33, 0.85);
    border: 1px solid rgba(255, 110, 199, 0.4);
    color: #ff6ec7;
    font-family: monospace;
    font-size: 12px;
    cursor: pointer;
    border-radius: 4px;
  `;
  document.body.appendChild(btn);

  btn.addEventListener('click', () => {
    pane.hidden = !pane.hidden;
    btn.textContent = pane.hidden ? 'Show Controls' : 'Hide Controls';
  });
};

createPane();
canvasSketch(sketch, settings);